INSERT INTO review (id, author, content, created_at, rating, product_id) VALUES (386, 'Trần Hoàng Nam', 'Hiệu năng thì không có gì để bàn, tuy nhiên máy hơi nặng và cục sạc to, bù lại sạc nhanh. Ship hàng cực tốc độ.', 2026-06-21 14:00:25.106402, 4, 1089);
INSERT INTO review (id, author, content, created_at, rating, product_id) VALUES (387, 'Lê Thùy Dương', 'Màu Starlight siêu đẹp, pin dùng cả ngày làm việc văn phòng không cần mang sạc. Gọn nhẹ, màn hình hiển thị sắc nét.', 2026-06-21 14:00:25.108055, 5, 1090);
INSERT INTO review (id, author, content, created_at, rating, product_id) VALUES (388, 'Phan Anh Tuấn', 'Máy mỏng nhẹ đẹp, dùng văn phòng rất mượt. Điểm trừ là Ram 16GB dùng nhiều tác vụ nặng hơi tràn tí, cơ mà cơ bản là quá tốt rồi.', 2026-06-21 14:00:25.110231, 4, 1090);
INSERT INTO review (id, author, content, created_at, rating, product_id) VALUES (389, 'Hoàng Gia Bảo', 'VGA siêu chất lượng từ ASUS ROG, tản nhiệt to nạc nhe, chạy cực mát và êm ái. Chiến game 4K mượt mà!', 2026-06-21 14:00:25.111838, 5, 1097);
INSERT INTO review (id, author, content, created_at, rating, product_id) VALUES (417, 'Admin Manager', 'sản phẩm tốt', 2026-06-21 14:37:43.522606, 5, 1121);
